using System;using System.IO;using System.Linq;using System.Drawing;using System.Reflection;using System.Collections.Generic;using System.Windows.Forms;using Musikbox;using MusikboxTests;
class Ui57Tests {
 static int n;static void Check(bool b,string s){if(!b)throw new Exception(s);n++;Console.WriteLine("PASS "+s);}static object Call(object o,string name,params object[] args){return o.GetType().GetMethod(name,BindingFlags.NonPublic|BindingFlags.Instance).Invoke(o,args);}static IEnumerable<Control> All(Control c){yield return c;foreach(Control x in c.Controls)foreach(var y in All(x))yield return y;}static void WaitForSearch(Func<bool> done){var clock=System.Diagnostics.Stopwatch.StartNew();while(!done()&&clock.ElapsedMilliseconds<5000){Application.DoEvents();System.Threading.Thread.Sleep(5);}Check(done(),"Asynchrone Suche beendet");}static void Pump(){for(int i=0;i<5;i++){Application.DoEvents();System.Threading.Thread.Sleep(30);}}
 [STAThread]static void Main(string[] args){Application.EnableVisualStyles();var songs=new[]{MediaMetadata.Read(Path.GetFullPath(args[0])),MediaMetadata.Read(Path.GetFullPath(args[0]))};songs[0].Title="First";songs[1].Title="Second";var project=new Project();project.Folders.Add(new BoxFolder{Name="Test",Theme="Test",Songs=songs.ToList()});using(var v=new MainView(Path.GetFullPath("verify/ui-layout.json"))){var c=new Controller(v,Path.GetFullPath("verify/ui-backups"),new Playback(new PlaybackTestDevice()));Call(c,"ReplaceProject",project,null,true);Check(v.WindowState==FormWindowState.Maximized,"Start maximiert");v.Show();v.WindowState=FormWindowState.Normal;v.ClientSize=new Size(1600,1000);v.Location=Point.Empty;Pump();v.Songs.Rows[1].Selected=true;v.Songs.CurrentCell=v.Songs.Rows[1].Cells[0];var nav=(Control)typeof(MainView).GetField("studioNavigation",BindingFlags.NonPublic|BindingFlags.Instance).GetValue(v);var audio=nav.Controls.OfType<Button>().Single(b=>b.Text=="Audio-Werkzeuge");audio.PerformClick();Pump();var children=nav.Controls.OfType<Button>().Where(b=>new[]{"Konvertierung","MP3Gain","fre:ac","FFmpeg"}.Contains(b.Text)).OrderBy(b=>b.Top).ToArray();Check(children.Select(b=>b.Text).SequenceEqual(new[]{"Konvertierung","MP3Gain","fre:ac","FFmpeg"})&&children.All(b=>b.Visible),"Audio-Untergruppen Reihenfolge und aufgeklappt");audio.PerformClick();Check(children.All(b=>!b.Visible),"Audio-Untergruppen zugeklappt");audio.PerformClick();foreach(string page in new[]{"Konvertierung","MP3Gain","fre:ac","FFmpeg","Coversuche","Coverbearbeitung","Covergestaltung","Cover zuweisen / exportieren"}){Call(c,"OpenStudioModule",page);Pump();Check(v.Songs.Visible&&v.Songs.Rows.Count==2,"Gemeinsame Titelliste in "+page);Check(v.Songs.SelectedRows.Count>0,"Auswahl erhalten in "+page);Check(v.ModuleHost.Visible&&v.ModuleHost.Controls.Count==1,"Arbeitsansicht "+page);}Call(c,"OpenStudioModule","Konvertierung");Check(All(v.ModuleHost).OfType<ComboBox>().Any(b=>b.Items.Count==5),"Fünf Tag-Konvertierungsarten bedienbar");var right=(Control)typeof(MainView).GetField("studioRight",BindingFlags.NonPublic|BindingFlags.Instance).GetValue(v);Check(Math.Abs(right.Top+v.TagPane.Bottom-v.PlayerPane.Top)<20,"Metadaten bis oberhalb Player");Check(!All(v.TagEditor).OfType<Label>().Any(l=>l.Visible&&l.Text.Contains("Ordnerzugriff")),"Überflüssiger Metadatenhinweis entfernt");Call(c,"OpenStudioModule","Tag-Editor");v.Songs.ClearSelection();v.Songs.Rows[1].Selected=true;v.Songs.CurrentCell=v.Songs.Rows[1].Cells[0];bool dialogSeen=false;var timer=new Timer{Interval=200};timer.Tick+=(s,e)=>{var d=Application.OpenForms.Cast<Form>().FirstOrDefault(f=>f.Text.StartsWith("Tracknummern-Assistent"));if(d==null)return;dialogSeen=true;Check(All(d).OfType<CheckBox>().Count()==3&&All(d).OfType<NumericUpDown>().Single().Value==1,"Tracknummern-Dialog und Vorgaben");var grid=All(d).OfType<DataGridView>().Single();Check(grid.Rows.Count==1&&grid.Rows[0].Cells[1].Value.ToString()=="1","Vorschau nur markierter Titel");timer.Stop();d.Close();};timer.Start();Call(c,"OpenTrackNumbers");timer.Dispose();Check(dialogSeen,"Tracknummern-Assistent integriert geöffnet");v.SearchBox.Text="First";WaitForSearch(()=>v.Songs.Rows.Count==1);Check(v.Songs.Rows.Count==1,"Normale Suche weiter funktionsfähig");v.SearchBox.Clear();using(var image=new Bitmap(v.Width,v.Height)){v.BringToFront();Pump();using(var graphics=Graphics.FromImage(image))graphics.CopyFromScreen(v.Location,Point.Empty,image.Size);image.Save("verify/ui57.png");}typeof(Controller).GetField("dirty",BindingFlags.NonPublic|BindingFlags.Instance).SetValue(c,false);v.Close();}Console.WriteLine("BESTANDEN "+n+" UI-Prüfungen (Mono/Xvfb, kein Windows-Mikrofon)");}
}
